import {completeSalaryProgression084} from './complete-salaries-084.js';
import {expandedPayOpportunity} from './expanded-pay.js';
import {escapeHTML as h} from './html.js';
const money=n=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):'Not assessed';
export function expandedPayPanel(s,o){
 const p=expandedPayOpportunity(s,o),e=p.payEvidence;if(!e){const estimate=completeSalaryProgression084(o);if(estimate)return '<section class="match-pay"><h3>Pay estimate</h3><p><strong>'+money(estimate.stages[0].amount)+' / year before tax</strong></p><p>After 5 years · planning scenario: '+money(estimate.stages[1].amount)+'</p><p>'+h(estimate.geography)+' · '+h(estimate.referencePeriod)+'</p><details><summary>Estimate basis and source</summary>'+estimate.notes.map(n=>'<p>'+h(n)+'</p>').join('')+estimate.sources.map(x=>'<a href="'+h(x.url)+'" target="_blank" rel="noopener">'+h(x.title||x.publisher)+' ↗</a>').join(' · ')+'</details></section>';return '<section class="match-pay"><h3>Pay and lifestyle</h3><p>Pay, education funding and first paid stage have not been assessed for this profession.</p></section>';}
 return '<section class="match-pay"><h3>Pay and lifestyle planning</h3><p><strong>'+money(e.amount)+' / year before tax</strong> · '+h(e.method)+'</p><p>'+h(e.geography)+' · '+h(e.referencePeriod)+'. This occupational wage proxy is an estimate for planning after qualification, not a measured starting salary or a job offer.</p><p>Lower-wage sensitivity: '+money(e.p10)+'–'+money(e.p25)+' (10th–25th percentiles). These are different workers, not a pay-growth forecast.</p>'+(e.entryComparable&&p.start?'<p><strong>'+(p.meetsAtStart?'The entry-wage proxy covers this budget.':'The entry-wage proxy does not cover this budget.')+'</strong> Monthly room: '+money(p.start.remaining)+'.</p>':'<p><strong>First paid-stage lifestyle coverage remains unresolved.</strong> '+h(e.qualificationReview?.reason||e.qualificationReview?.note||'This wage scope or preparation route needs a more specific first-job reference.')+'</p>'+(p.qualifiedBudget?'<p>Qualified-role wage comparison only: '+money(p.qualifiedBudget.remaining)+' monthly room.</p>':''))+'<p>Training cost and aid remain unverified. This comparison includes the loan payments you entered; it does not assume that education is funded. Full-time employee wages do not establish self-employed or project income.</p><details><summary>Pay sources and limits</summary><p>'+h(e.mapping)+' · '+h(e.wageTitle)+' ('+h(e.wageSOC)+')</p><ul>'+e.limitations.map(t=>'<li>'+h(t)+'</li>').join('')+'</ul><a href="'+h(e.sourceURL)+'" target="_blank" rel="noopener">Wage proxy source ↗</a> · <a href="'+h(e.distributionURL)+'" target="_blank" rel="noopener">Wage distribution ↗</a> · <a href="'+h(e.methodologyURL)+'" target="_blank" rel="noopener">Method ↗</a></details></section>';
}
